    function safeJsonParse_ACU(str, fallback = null) {
        try {
            return JSON.parse(str);
        }
        catch (e) {
            return fallback;
        }
    }
    function stripJsonCommentsPreservingStrings_ACU(input) {
        if (typeof input !== 'string' || !input)
            return input;
        let result = '';
        let inString = false;
        let escapeNext = false;
        let inLineComment = false;
        let inBlockComment = false;
        for (let i = 0; i < input.length; i++) {
            const char = input[i];
            const nextChar = input[i + 1] || '';
            if (inLineComment) {
                if (char === '\n' || char === '\r') {
                    inLineComment = false;
                    result += char;
                }
                continue;
            }
            if (inBlockComment) {
                if (char === '*' && nextChar === '/') {
                    inBlockComment = false;
                    i++;
                }
                continue;
            }
            if (escapeNext) {
                result += char;
                escapeNext = false;
                continue;
            }
            if (inString) {
                result += char;
                if (char === '\\') {
                    escapeNext = true;
                }
                else if (char === '"') {
                    inString = false;
                }
                continue;
            }
            if (char === '"') {
                inString = true;
                result += char;
                continue;
            }
            if (char === '/' && nextChar === '/') {
                inLineComment = true;
                i++;
                continue;
            }
            if (char === '/' && nextChar === '*') {
                inBlockComment = true;
                i++;
                result += ' ';
                continue;
            }
            result += char;
        }
        return result;
    }
    function safeJsonParseWithJsoncComments_ACU(str, fallback = null) {
        try {
            return JSON.parse(str);
        }
        catch (e) { }
        try {
            return JSON.parse(stripJsonCommentsPreservingStrings_ACU(str));
        }
        catch (e) {
            return fallback;
        }
    }
    function safeJsonStringify_ACU(obj, fallback = '{}') {
        try {
            return JSON.stringify(obj);
        }
        catch (e) {
            return fallback;
        }
    }

