    async function initStorageProvider() {
        const mode = getCurrentStorageMode();
        if (currentProvider) {
            currentProvider.dispose();
            currentProvider = null;
        }
        currentProvider = createProvider(mode);
        logDebug_ACU(`[Chiến Lược Lưu Trữ] Khởi tạo Provider: ${mode}`);
        try {
            const result = await currentProvider.loadFromChat();
            logDebug_ACU(`[Chiến Lược Lưu Trữ] Tải dữ liệu hoàn tất: loaded=${result.loaded}, source=${result.source}`);
            if (mode === 'sqlite' && !result.loaded && result.error) {
                logError_ACU(`[Chiến Lược Lưu Trữ] Tải SQLite thất bại, tự động fallback về chế độ gốc: ${result.error}`);
                currentProvider.dispose();
                currentProvider = createProvider('native');
                await currentProvider.loadFromChat();
            }
        }
        catch (e) {
            logError_ACU(`[Chiến Lược Lưu Trữ] Khởi tạo thất bại: ${e?.message}`);
            if (mode === 'sqlite') {
                logError_ACU('[Chiến Lược Lưu Trữ] Khởi tạo SQLite bất thường, fallback về chế độ gốc');
                if (currentProvider)
                    currentProvider.dispose();
                currentProvider = createProvider('native');
                await currentProvider.loadFromChat();
            }
        }
    }
    async function switchStorageMode(mode) {
        const currentMode = currentProvider?.mode;
        if (currentMode === mode) {
            logDebug_ACU(`[Chiến Lược Lưu Trữ] Đã ở chế độ ${mode}, không cần chuyển đổi`);
            return;
        }
        logDebug_ACU(`[Chiến Lược Lưu Trữ] Chuyển đổi chế độ: ${currentMode || 'none'} → ${mode}`);
        if (currentProvider) {
            currentProvider.dispose();
            currentProvider = null;
        }
        currentProvider = createProvider(mode);
        try {
            const result = await currentProvider.loadFromChat();
            logDebug_ACU(`[Chiến Lược Lưu Trữ] Chuyển đổi hoàn tất: loaded=${result.loaded}, source=${result.source}`);
            if (mode === 'sqlite' && !result.loaded && result.error) {
                logError_ACU(`[Chiến Lược Lưu Trữ] Chuyển đổi SQLite thất bại, fallback về chế độ gốc: ${result.error}`);
                currentProvider.dispose();
                currentProvider = createProvider('native');
                await currentProvider.loadFromChat();
                throw new Error(`Chuyển đổi chế độ SQLite thất bại: ${result.error}. Đã tự động lùi về chế độ gốc.`);
            }
        }
        catch (e) {
            if (e.message?.includes('Đã tự động lùi về'))
                throw e;
            logError_ACU(`[Chiến Lược Lưu Trữ] Chuyển đổi bất thường: ${e?.message}`);
            if (!currentProvider || !currentProvider.getCurrentData()) {
                currentProvider?.dispose();
                currentProvider = createProvider('native');
                await currentProvider.loadFromChat();
            }
            throw e;
        }
    }
    function disposeStorageProvider() {
        if (currentProvider) {
            logDebug_ACU(`[Chiến Lược Lưu Trữ] Hủy Provider hiện tại: ${currentProvider.mode}`);
            currentProvider.dispose();
            currentProvider = null;
        }
    }
    async function reloadStorageProvider() {
        invalidateTableRuntimeRevision_ACU({ reason: 'reloadStorageProvider' });
        if (!currentProvider) {
            await initStorageProvider();
            return;
        }
        const mode = currentProvider.mode;
        logDebug_ACU(`[Chiến Lược Lưu Trữ] Tải lại dữ liệu: ${mode}`);
        if (mode === 'sqlite') {
            currentProvider.dispose();
            currentProvider = createProvider('sqlite');
        }
        try {
            const result = await currentProvider.loadFromChat();
            if (mode === 'sqlite' && !result.loaded && result.error) {
                throw new Error(result.error);
            }
        }
        catch (e) {
            logError_ACU(`[Chiến Lược Lưu Trữ] Tải lại thất bại: ${e?.message}`);
            if (mode === 'sqlite') {
                currentProvider.dispose();
                currentProvider = createProvider('native');
                await currentProvider.loadFromChat();
            }
        }
    }
    function getCurrentProviderMode() {
        return currentProvider?.mode ?? null;
    }
    function createProvider(mode) {
        switch (mode) {
            case 'sqlite':
                return new SqlTableService();
            case 'native':
            default:
                return new NativeTableServiceAdapter();
        }
    }

