            const bo = Number.isFinite(templateObj?.[b]?.[TABLE_ORDER_FIELD_ACU]) ? Math.trunc(templateObj[b][TABLE_ORDER_FIELD_ACU]) : Infinity;
            if (ao !== bo)
                return ao - bo;
            return String(a).localeCompare(String(b));
