    async function executeContentOptimizationWithConfirm_ACU(messageIndex, content, userMessage, totalLoops, currentLoop = 1, currentContent = null, totalOptimizations = []) {
        let workingContent = currentContent !== null ? currentContent : content;
        logDebug_ACU(`[Tối Ưu Hóa Chính Văn-Xác Nhận Thủ Công] Thực thi vòng tối ưu hóa thứ ${currentLoop}/${totalLoops}`);
        const result = await performContentOptimization_ACU(workingContent, {
            currentLoop: currentLoop,
            userMessage: userMessage
        });
        if (!result.success) {
            logDebug_ACU(`[Tối Ưu Hóa Chính Văn-Xác Nhận Thủ Công] Vòng tối ưu hóa thứ ${currentLoop} thất bại:`, result.error);
            if (currentLoop === 1) {
                showToastr_ACU('error', `Tối ưu hóa chính văn thất bại: ${result.error}`);
                return false;
            }
            await triggerAutomaticUpdateIfNeeded_ACU();
            return true;
        }
        if (!result.optimizations || result.optimizations.length === 0) {
            logDebug_ACU(`[Tối Ưu Hóa Chính Văn-Xác Nhận Thủ Công] Vòng thứ ${currentLoop} không cần tối ưu hóa, nguyên tác đã đủ tốt`);
            if (currentLoop < totalLoops) {
                return await executeContentOptimizationWithConfirm_ACU(messageIndex, content, userMessage, totalLoops, currentLoop + 1, workingContent, totalOptimizations);
            }
            else {
                if (totalOptimizations.length > 0) {
                    showToastr_ACU('success', `Tối ưu hóa chính văn hoàn tất, tổng cộng ${totalLoops} vòng tối ưu hóa, tích lũy ${totalOptimizations.length} chỗ cải thiện`);
                }
                else {
                    showToastr_ACU('info', 'Chính văn không cần tối ưu hóa');
                }
                await triggerAutomaticUpdateIfNeeded_ACU();
                return true;
            }
        }
        const newTotalOptimizations = totalOptimizations.concat(result.optimizations);
        return new Promise((resolve) => {
            showOptimizationDiffDialogForLoop_ACU(messageIndex, {
                optimizations: result.optimizations,
                summary: `Vòng tối ưu hóa thứ ${currentLoop}/${totalLoops}, vòng này có ${result.optimizations.length} chỗ cải thiện`,
                optimizedContent: result.optimizedContent,
                currentLoop: currentLoop,
                totalLoops: totalLoops,
                totalOptimizations: newTotalOptimizations
            }, async (action) => {
                if (action === 'apply') {
                    if (currentLoop < totalLoops) {
                        const nextResult = await executeContentOptimizationWithConfirm_ACU(messageIndex, content, userMessage, totalLoops, currentLoop + 1, result.optimizedContent, newTotalOptimizations);
                        resolve(nextResult);
                    }
                    else {
                        await replaceChatMessage_ACU(messageIndex, result.optimizedContent);
                        showToastr_ACU('success', `Tối ưu hóa chính văn hoàn tất, tổng cộng ${totalLoops} vòng tối ưu hóa, tích lũy ${newTotalOptimizations.length} chỗ cải thiện`);
                        await triggerAutomaticUpdateIfNeeded_ACU();
                        resolve(true);
                    }
                }
                else if (action === 'skip') {
                    if (currentLoop < totalLoops) {
                        const nextResult = await executeContentOptimizationWithConfirm_ACU(messageIndex, content, userMessage, totalLoops, currentLoop + 1, workingContent,
                            totalOptimizations
                        );
                        resolve(nextResult);
                    }
                    else {
                        if (totalOptimizations.length > 0) {
                            await triggerAutomaticUpdateIfNeeded_ACU();
                            showToastr_ACU('success', `Tối ưu hóa chính văn hoàn tất, tổng cộng ${totalLoops} vòng tối ưu hóa, tích lũy ${totalOptimizations.length} chỗ cải thiện`);
                        }
                        else {
                            showToastr_ACU('info', 'Đã bỏ qua tối ưu hóa chính văn');
                        }
                        await triggerAutomaticUpdateIfNeeded_ACU();
                        resolve(true);
                    }
                }
                else {
                    await triggerAutomaticUpdateIfNeeded_ACU();
                    resolve(true);
                }
            });
        });
    }

