                        const fallbackLabel = `Nhập_Mẫu_${new Date().toISOString().slice(0, 19).replace(/[:T]/g, '-')}`;
                        const selectedChatPresetName = normalizeTemplatePresetSelectionValue_ACU(jQuery_API_ACU($templateChatPresetSelect_ACU).val());
